-- EDI 해시 식별값을 원본 코드·옵션·주문 정보로 전환
-- 기존 업무 데이터와 반영 수량은 유지. 이전 실행 파일 종료 후 새 실행 파일 사용
USE YOZM;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @Lock int;
EXEC @Lock=sys.sp_getapplock @Resource=N'1000',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=30000;
IF @Lock<0 THROW 50001,N'다른 EDI 작업이 진행 중입니다.',1;
IF COL_LENGTH('dbo.BM_EdiImportFile','FileHash') IS NULL
BEGIN
 COMMIT;
 RETURN;
END;
SELECT * INTO #ActualBefore FROM dbo.PM_ForecastOrderActual WITH (HOLDLOCK,TABLOCK);
SELECT * INTO #BackupBefore FROM dbo.BM_EdiForecastBackup WITH (HOLDLOCK,TABLOCK);
SELECT RowId,FileId,CorpId,CustCode,ItemCode,Qty,Factor,Amount,Applied,OrderDate,DeliveryDate INTO #RowsBefore
FROM dbo.BM_EdiImportRow WITH (UPDLOCK,HOLDLOCK,TABLOCK);
SELECT * INTO #MapsBefore FROM dbo.BM_EdiItemMap WITH (UPDLOCK,HOLDLOCK,TABLOCK);
CREATE TABLE #Keys(RowId bigint PRIMARY KEY,OldSource varchar(64),OldRow varchar(64),SourceKey nvarchar(700),RowKey nvarchar(700));
