IF (SELECT COUNT(*) FROM #MapKeys)<>(SELECT COUNT(*) FROM dbo.BM_EdiItemMap)
 OR EXISTS(SELECT 1 FROM dbo.BM_EdiItemMap m WHERE NOT EXISTS(SELECT 1 FROM #MapKeys k WHERE k.CorpId=m.CorpId AND k.CustCode=m.CustCode AND k.OldSource COLLATE Latin1_General_100_BIN2=m.SourceKey))
 THROW 50001,N'품목 연결 이력이 변경되었습니다.',1;
ALTER TABLE dbo.BM_EdiItemMap DROP CONSTRAINT PK_BM_EdiItemMap;
DROP INDEX UX_BM_EdiAppliedRow ON dbo.BM_EdiImportRow;
-- 기존 해시와 동일하게 문자열을 정확히 비교, 대소문자·기호 오인식 방지
ALTER TABLE dbo.BM_EdiItemMap ALTER COLUMN SourceKey nvarchar(700) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE dbo.BM_EdiImportRow ALTER COLUMN SourceKey nvarchar(700) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE dbo.BM_EdiImportRow ALTER COLUMN RowKey nvarchar(700) COLLATE Latin1_General_100_BIN2 NOT NULL;
UPDATE m SET SourceKey=k.NewSource FROM dbo.BM_EdiItemMap m JOIN #MapKeys k ON k.CorpId=m.CorpId AND k.CustCode=m.CustCode AND k.OldSource COLLATE Latin1_General_100_BIN2=m.SourceKey;
UPDATE r SET SourceKey=k.SourceKey,RowKey=k.RowKey FROM dbo.BM_EdiImportRow r JOIN #Keys k ON k.RowId=r.RowId;
ALTER TABLE dbo.BM_EdiItemMap ADD CONSTRAINT PK_BM_EdiItemMap PRIMARY KEY NONCLUSTERED(CorpId,CustCode,SourceKey);
CREATE UNIQUE NONCLUSTERED INDEX UX_BM_EdiAppliedRow ON dbo.BM_EdiImportRow(CorpId,RowKey) WHERE Applied=1;
ALTER TABLE dbo.BM_EdiImportFile DROP CONSTRAINT UQ_BM_EdiImportFile;
ALTER TABLE dbo.BM_EdiImportFile ALTER COLUMN FileHash nvarchar(260) NOT NULL;
UPDATE dbo.BM_EdiImportFile SET FileHash=CASE WHEN FileName=N'직접 등록' THEN N'수동:'+CONVERT(nvarchar(20),FileId) ELSE FileName END;
EXEC sys.sp_rename 'dbo.BM_EdiImportFile.FileHash','FileKey','COLUMN';
EXEC(N'ALTER TABLE dbo.BM_EdiImportFile ADD CONSTRAINT UQ_BM_EdiImportFile UNIQUE(CorpId,FileKey)');
IF EXISTS(SELECT * FROM #ActualBefore EXCEPT SELECT * FROM dbo.PM_ForecastOrderActual)
 OR EXISTS(SELECT * FROM dbo.PM_ForecastOrderActual EXCEPT SELECT * FROM #ActualBefore)
 OR EXISTS(SELECT * FROM #BackupBefore EXCEPT SELECT * FROM dbo.BM_EdiForecastBackup)
 OR EXISTS(SELECT * FROM dbo.BM_EdiForecastBackup EXCEPT SELECT * FROM #BackupBefore)
 OR EXISTS(SELECT * FROM #RowsBefore EXCEPT SELECT RowId,FileId,CorpId,CustCode,ItemCode,Qty,Factor,Amount,Applied,OrderDate,DeliveryDate FROM dbo.BM_EdiImportRow)
 THROW 50001,N'업무 데이터 보존 검증 실패',1;
IF EXISTS(SELECT CorpId,CustCode,SourceCode,SourceName,ItemCode,Factor,ModId,ModDt FROM #MapsBefore EXCEPT SELECT CorpId,CustCode,SourceCode,SourceName,ItemCode,Factor,ModId,ModDt FROM dbo.BM_EdiItemMap)
 THROW 50001,N'품목 연결 보존 검증 실패',1;
DECLARE @Descriptions TABLE(TableName sysname,ColumnName sysname,Description nvarchar(300));
INSERT @Descriptions VALUES
('BM_EdiImportFile','FileKey',N'등록 파일명 또는 직접 등록 식별값'),
('BM_EdiImportRow','SourceKey',N'원본 상품 식별값(상품코드 또는 품명·옵션)'),
('BM_EdiItemMap','SourceKey',N'원본 상품 식별값(상품코드 또는 품명·옵션)'),
('BM_EdiImportRow','RowKey',N'주문 식별값(거래처·주문번호·상품·반복순번)');
DECLARE @t sysname,@n sysname,@d nvarchar(300);
DECLARE descriptions CURSOR LOCAL FAST_FORWARD FOR SELECT TableName,ColumnName,Description FROM @Descriptions;
OPEN descriptions;
FETCH NEXT FROM descriptions INTO @t,@n,@d;
WHILE @@FETCH_STATUS=0
BEGIN
 IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE major_id=OBJECT_ID('dbo.'+@t) AND minor_id=COLUMNPROPERTY(OBJECT_ID('dbo.'+@t),@n,'ColumnId') AND name='MS_Description')
 EXEC sys.sp_updateextendedproperty @name=N'MS_Description',@value=@d,@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=@t,@level2type=N'COLUMN',@level2name=@n;
 ELSE
 EXEC sys.sp_addextendedproperty @name=N'MS_Description',@value=@d,@level0type=N'SCHEMA',@level0name=N'dbo',@level1type=N'TABLE',@level1name=@t,@level2type=N'COLUMN',@level2name=@n;
 FETCH NEXT FROM descriptions INTO @t,@n,@d;
END;
CLOSE descriptions;
DEALLOCATE descriptions;
COMMIT;
